import sqlite3
from langchain_core.tools import tool

DB = "fitness.db"


def _role(c, uid):
    r = c.execute("SELECT role FROM users WHERE id = ?", (uid,)).fetchone()
    return r[0] if r else None


@tool
def transfer_client_program_ownership(program_id: int, new_coach_id: int, keep_old_as_viewer: bool = True) -> str:
    c = sqlite3.connect(DB)
    try:
        p = c.execute("SELECT owner_id FROM programs WHERE id = ?", (program_id,)).fetchone()
        if not p:
            return f"Program {program_id} not found"
        old = p[0]
        if old == new_coach_id:
            return "New coach already owns this program"
        if _role(c, new_coach_id) != "coach":
            return f"User {new_coach_id} is not a coach"
        c.execute("UPDATE programs SET owner_id = ? WHERE id = ?", (new_coach_id, program_id))
        c.execute(
            "DELETE FROM program_access WHERE program_id = ? AND user_id = ?",
            (program_id, new_coach_id),
        )
        c.execute(
            "DELETE FROM program_access WHERE program_id = ? AND user_id = ?",
            (program_id, old),
        )
        if keep_old_as_viewer:
            c.execute(
                "INSERT INTO program_access (program_id, user_id, level) VALUES (?, ?, 'view')",
                (program_id, old),
            )
        c.commit()
        return f"Program {program_id} moved from coach {old} to coach {new_coach_id}"
    except sqlite3.Error as e:
        c.rollback()
        return f"Database error: {e}"
    finally:
        c.close()

import subprocess
from dataclasses import dataclass

import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("fitness")


@dataclass
class ImportResult:
    exit_code: int
    notified: bool
    status: int


@mcp.tool()
def run_workout_import_and_notify(user_id: str, webhook_url: str) -> ImportResult:
    p = subprocess.run(["python", "scripts/import_wearable.py", "--user", user_id], capture_output=True, text=True, timeout=300)
    body = {"user_id": user_id, "exit_code": p.returncode, "output": p.stdout[-500:]}
    r = requests.post(webhook_url, json=body, timeout=10)
    return ImportResult(p.returncode, r.ok, r.status_code)

import sqlite3
from dataclasses import dataclass

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("fitness")
db = sqlite3.connect("fitness.db", check_same_thread=False)


@dataclass
class InviteResult:
    accepted: bool
    inviter_name: str
    access_level: str


@mcp.tool()
def accept_gym_buddy_invite(invite_code: str, user_id: int) -> InviteResult:
    row = db.execute(
        "SELECT i.id, i.inviter_id, i.level, u.name FROM buddy_invites i JOIN users u ON u.id = i.inviter_id WHERE i.code = ? AND i.invitee_id = ? AND i.status = 'pending'",
        (invite_code, user_id),
    ).fetchone()
    if not row:
        return InviteResult(False, "", "")
    db.execute("INSERT OR REPLACE INTO log_access (owner_id, grantee_id, level) VALUES (?, ?, ?)", (user_id, row[1], row[2]))
    db.execute("UPDATE buddy_invites SET status = 'accepted' WHERE id = ?", (row[0],))
    db.commit()
    return InviteResult(True, row[3], row[2])
